turn null; // Bill not found\n }\n }\n \n // Get bill items\n List<Map<String, Object>> items = new ArrayList<>();\n try (PreparedStatement itemsStmt = conn.prepareStatement(itemsSql)) {\n itemsStmt.setInt(1, billId);\n ResultSet itemsRs = itemsStmt.executeQuery();\n \n while (itemsRs.next()) {\n Map<String, Object> item = new HashMap<>();\n item.put(\"name\", itemsRs.getString(\"name\"));\n item.put(\"quantity\", itemsRs.getInt(\"quantity\"));\n item.put(\"unitPrice\", itemsRs.getDouble(\"unit_price\"));\n item.put(\"total\", itemsRs.getInt(\"quantity\") * itemsRs.getDouble(\"unit_price\"));\n items.add(item);\n }\n }\n \n billDetails.put(\"items\", items);\n return billDetails;\n \n } catch (SQLException e) {\n e.printStackTrace();\n return null;\n }\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"I see the issue. My previous edit didn't work correctly. Let me fix it:
