erAddress || 'N/A'}<br>\n Phone: ${billData.customerTelephone || 'N/A'}<br>\n Account: ${billData.customerAccountNumber}\n </p>\n </div>\n <div class=\"col-md-6 text-end\">\n <h5>Bill Details:</h5>\n <p>\n <strong>Bill ID:</strong> #${billData.billId}<br>\n <strong>Date:</strong> ${billDate}<br>\n <strong>Status:</strong> <span class=\"badge bg-success\">Paid</span>\n </p>\n </div>\n </div>\n \n <div class=\"table-responsive mb-4\">\n <table class=\"table table-bordered\">\n <thead class=\"table-dark\">\n <tr>\n <th>Item</th>\n <th class=\"text-center\">Quantity</th>\n <th class=\"text-end\">Unit Price</th>\n <th class=\"text-end\">Total</th>\n </tr>\n </thead>\n <tbody>\n ${itemsHtml}\n </tbody>\n <tfoot>\n <tr class=\"table-secondary\">\n <th colspan=\"3\" class=\"text-end\">Grand Total:</th>\n <th class=\"text-end\">$${billData.totalAmount.toFixed(2)}</th>\n </tr>\n </tfoot>\n </table>\n </div>\n \n <div class=\"text-center\">\n <p class=\"text-muted\">Thank you for your business!</p>\n <small>This is a computer-generated bill.</small>\n </div>\n `;\n \n $('#printableBill').html(billHtml);\n }\n\n // Print bill\n $('#printBillBtn').click(function () {\n const printContent = $('#printableBill').html();\n const printWindow = window.open('', '_blank');\n \n printWindow.document.write(`\n <!DOCTYPE html>\n <html>\n <head>\n <title>Bill - Pahana Edu Management</title>\n <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n <style>\n @media print {\n .no-print { display: none !important; }\n body { margin: 0; }\n .container { max-width: none; }\n }\n body { font-family: Arial, sans-serif; }\n .bill-header h2 { color: #0d6efd; }\n </style>\n </head>\n <body>\n <div class=\"container mt-4\">\n ${printContent}\n </div>\n <script>\n window.onload = function() {\n window.print();\n window.onafterprint = function() {\n window.close();\n }\n }\n </script>\n </body>\n </html>\n `);\n \n printWindow.document.close();\n });\n\n // New order button\n $('#newOrderBtn').click(function () {\n // Reset order form\n orderItems = [];\n $('#customerSelect').val('');\n $('#customerInfo').hide();\n $('#itemSelect').val('');\n $('#itemPrice').val('');\n $('#itemQuantity').val('1');\n $('#availableStock').text('0');\n updateOrderTable();\n updatePlaceOrderButton();\n \n // Hide bill section\n $('#billDisplaySection').hide();\n \n // Scroll to top\n $('.place-order')[0].scrollIntoView({ behavior: 'smooth' });\n });\n\n // Initialize tooltips"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Now let me add the bill loading and printing functions:
