 1	package com.example.pahanaedubackend.dao;
 2	
 3	import com.example.pahanaedubackend.model.Item;
 4	import com.example.pahanaedubackend.util.DBUtil;
 5	
 6	import java.sql.Connection;
 7	import java.sql.PreparedStatement;
 8	import java.sql.ResultSet;
 9	import java.sql.SQLException;
 10	import java.util.ArrayList;
 11	import java.util.List;
 12	
 13	public class ItemDAO {
 14	 public boolean addItem(Item item) {
 15	 String sql = "INSERT INTO items (name, unit_price, quantity) VALUES (?, ?, ?)";
 16	
 17	 try (Connection conn = DBUtil.getInstance().getConnection();
 18	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 19	
 20	 stmt.setString(1, item.getName());
 21	 stmt.setDouble(2, item.getPrice());
 22	 stmt.setInt(3, item.getQuantity());
 23	
 24	 return stmt.executeUpdate() > 0;
 25	 } catch (SQLException e) {
 26	 e.printStackTrace();
 27	 return false;
 28	 }
 29	 }
 30	
 31	 public List<Item> getAllItems() {
 32	 List<Item> items = new ArrayList<>();
 33	 String sql = "SELECT * FROM items ORDER BY id DESC";
 34	
 35	 try (Connection conn = DBUtil.getInstance().getConnection();
 36	 PreparedStatement stmt = conn.prepareStatement(sql);
 37	 ResultSet rs = stmt.executeQuery()) {
 38	
 39	 while (rs.next()) {
 40	 Item item = new Item();
 41	 item.setId(rs.getInt("id"));
 42	 item.setName(rs.getString("name"));
 43	 item.setPrice(rs.getDouble("unit_price"));
 44	 item.setQuantity(rs.getInt("quantity"));
 45	
 46	 items.add(item);
 47	 }
 48	 } catch (SQLException e) {
 49	 e.printStackTrace();
 50	 }
 51	
 52	 return items;
 53	 }
 54	
 55	 public boolean updateItem(Item item) {
 56	 String sql = "UPDATE items SET name = ?, unit_price = ?, quantity = ? WHERE id = ?";
 57	
 58	 try (Connection conn = DBUtil.getInstance().getConnection();
 59	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 60	
 61	 stmt.setString(1, item.getName());
 62	 stmt.setDouble(2, item.getPrice());
 63	 stmt.setInt(3, item.getQuantity());
 64	 stmt.setInt(4, item.getId());
 65	
 66	 return stmt.executeUpdate() > 0;
 67	
 68	 } catch (SQLException e) {
 69	 e.printStackTrace();
 70	 return false;
 71	 }
 72	 }
 73	
 74	 public boolean deleteItem(int itemId) {
 75	 String sql = "DELETE FROM items WHERE id = ?";
 76	
 77	 try (Connection conn = DBUtil.getInstance().getConnection();
 78	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 79	
 80	 stmt.setInt(1, itemId);
 81	 return stmt.executeUpdate() > 0;
 82	
 83	 } catch (SQLException e) {
 84	 e.printStackTrace();
 85	 return false;
 86	 }
 87	 }
 88	
 89	 public Item getItemById(int id) {
 90	 String sql = "SELECT * FROM items WHERE id = ?";
 91	 try (Connection conn = DBUtil.getInstance().getConnection();
 92	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 93	
 94	 stmt.setInt(1, id);
 95	 ResultSet rs = stmt.executeQuery();
 96	
 97	 if (rs.next()) {
 98	 Item item = new Item();
 99	 item.setId(rs.getInt("id"));
 100	 item.setName(rs.getString("name"));
 101	 item.setPrice(rs.getDouble("unit_price"));
 102	 item.setQuantity(rs.getInt("quantity"));
 103	 return item;
 104	 }
 105	
 106	 } catch (SQLException e) {
 107	 e.printStackTrace();
 108	 }
 109	 return null;
 110	 }
 111	
 112	 public boolean updateStock(int itemId, int newStock) {
 113	 String sql = "UPDATE items SET stock = ? WHERE id = ?";
 114	
 115	 try (Connection conn = DBUtil.getInstance().getConnection();
 116	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 117	
 118	 stmt.setInt(1, newStock);
 119	 stmt.setInt(2, itemId);
 120	
 121	 int rowsUpdated = stmt.executeUpdate();
 122	 return rowsUpdated > 0;
 123	
 124	 } catch (SQLException e) {
 125	 e.printStackTrace();
 126	 }
 127	
 128	 return false;
 129	 }
 130	}
