 12	
 13	@WebServlet("/item-delete")
 14	public class DeleteItemServlet extends HttpServlet {
 15	 private final ItemService itemService = new ItemService();
 16	
 17	 @Override
 18	 protected void doDelete(HttpServletRequest request, HttpServletResponse response)
 19	 throws ServletException, IOException {
 20	
 21	 response.setContentType("application/json");
 22	 response.setCharacterEncoding("UTF-8");
 23	
 24	 HttpSession session = request.getSession(false);
 25	 if (session == null || session.getAttribute("admin") == null) {
 26	 response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
 27	 response.getWriter().write("{\"success\":false,\"message\":\"Unauthorized: Admin login required\"}");
 28	 return;
 29	 }
 30	
 31	 int itemId;
 32	 try {
 33	 itemId = Integer.parseInt(request.getParameter("id"));
 34	 } catch (NumberFormatException e) {
 35	 response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
 36	 response.getWriter().write("{\"success\":false,\"message\":\"Invalid item ID\"}");
 37	 return;
 38	 }
 39	
 40	 // Check if item is used in bills before attempting deletion
 41	 if (itemService.isItemUsedInBills(itemId)) {
 42	 response.setStatus(HttpServletResponse.SC_CONFLICT);
 43	 response.getWriter().write("{\"success\":false,\"message\":\"Cannot delete item: This item is used in existing bills. Please remove it from all bills before deletion.\"}");
 44	 return;
 45	 }
 46	
 47	 boolean deleted = itemService.deleteItem(itemId);
 48	
 49	 if (deleted) {
 50	 response.getWriter().write("{\"success\":true,\"message\":\"Item deleted successfully\"}");
 51	 } else {
 52	 response.setStatus(HttpServletResponse.SC_NOT_FOUND);
 53	 response.getWriter().write("{\"success\":false,\"message\":\"Item not found or delete failed\"}");
 54	 }
 55	 }
 56	}
