 10	public class BillDAO {
 11	 public boolean createBill(Bill bill, List<BillItem> billItems) {
 12	 String billSql = "INSERT INTO bills (bill_date, total_amount, customer_account_number) VALUES (?, ?, ?)";
 13	 String billItemSql = "INSERT INTO bill_items (bill_id, item_id, quantity, unit_price) VALUES (?, ?, ?, ?)";
 14	
 15	 try (Connection conn = DBUtil.getInstance().getConnection()) {
 16	 conn.setAutoCommit(false);
 17	
 18	 try (PreparedStatement billStmt = conn.prepareStatement(billSql, Statement.RETURN_GENERATED_KEYS)) {
 19	 billStmt.setDate(1, new java.sql.Date(bill.getBillDate().getTime()));
 20	 billStmt.setDouble(2, bill.getTotal());
 21	 billStmt.setString(3, (bill.getCustomerAccountNumber()));
 22	
 23	 billStmt.executeUpdate();
 24	
 25	 ResultSet generatedKeys = billStmt.getGeneratedKeys();
 26	 if (generatedKeys.next()) {
 27	 int billId = generatedKeys.getInt(1);
 28	
 29	 try (PreparedStatement itemStmt = conn.prepareStatement(billItemSql)) {
 30	 for (BillItem item : billItems) {
 31	 itemStmt.setInt(1, billId);
 32	 itemStmt.setInt(2, item.getItemId());
 33	 itemStmt.setInt(3, item.getQuantity());
 34	 itemStmt.setDouble(4, item.getPrice());
 35	 itemStmt.addBatch();
 36	 }
 37	 itemStmt.executeBatch();
 38	 }
 39	
 40	 conn.commit();
 41	 return true;
 42	 }
 43	 } catch (SQLException e) {
 44	 conn.rollback();
 45	 e.printStackTrace();
 46	 }
 47	 } catch (SQLException e) {
 48	 e.printStackTrace();
