 17	 private final BillService billService = new BillService();
 18	
 19	 @Override
 20	 protected void doGet(HttpServletRequest request, HttpServletResponse response)
 21	 throws ServletException, IOException {
 22	
 23	 response.setContentType("application/json");
 24	 response.setCharacterEncoding("UTF-8");
 25	
 26	 HttpSession session = request.getSession(false);
 27	 if (session == null || session.getAttribute("admin") == null) {
 28	 response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
 29	 response.getWriter().write("{\"success\":false,\"message\":\"Unauthorized: Admin login required\"}");
 30	 return;
 31	 }
 32	
 33	 int billId;
 34	 try {
 35	 billId = Integer.parseInt(request.getParameter("id"));
 36	 } catch (NumberFormatException e) {
 37	 response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
 38	 response.getWriter().write("{\"success\":false,\"message\":\"Invalid bill ID\"}");
 39	 return;
 40	 }
 41	
 42	 Map<String, Object> billDetails = billService.getBillDetails(billId);
 43	
 44	 if (billDetails != null) {
 45	 ObjectMapper mapper = new ObjectMapper();
 46	 mapper.writeValue(response.getWriter(), billDetails);
 47	 } else {
 48	 response.setStatus(HttpServletResponse.SC_NOT_FOUND);
 49	 response.getWriter().write("{\"success\":false,\"message\":\"Bill not found\"}");
 50	 }
 51	 }
