 17	 public int createBill(String customerAccountNumber, List<BillItem> billItems) {
 18	 double total = 0.0;
 19	 List<BillItem> validItems = new ArrayList<>();
 20	
 21	 for (BillItem billItem : billItems) {
 22	 Item item = itemDAO.getItemById(billItem.getItemId());
 23	 if (item != null && item.getQuantity() >= billItem.getQuantity()) {
 24	 double itemTotal = item.getPrice() * billItem.getQuantity();
 25	 total += itemTotal;
 26	
 27	 billItem.setPrice(item.getPrice());
 28	 validItems.add(billItem);
 29	
 30	 // update item stock
 31	 itemDAO.updateStock(item.getId(), item.getQuantity() - billItem.getQuantity());
 32	 } else {
 33	 return -1; // insufficient stock or invalid item
 34	 }
 35	 }
 36	
 37	 Bill bill = new Bill();
 38	 bill.setBillDate(new Date());
 39	 bill.setTotal(total);
 40	 bill.setCustomerAccountNumber(customerAccountNumber);
 41	
 42	 return billDAO.createBill(bill, validItems);
 43	 }
