 54	 public Map<String, Object> getBillDetails(int billId) {
 55	 String billSql = "SELECT b.*, c.full_name, c.address, c.telephone " +
 56	 "FROM bills b " +
 57	 "LEFT JOIN customer c ON b.customer_account_number = c.account_number " +
 58	 "WHERE b.id = ?";
 59	
 60	 String itemsSql = "SELECT bi.*, i.name as item_name " +
 61	 "FROM bill_items bi " +
 62	 "JOIN items i ON bi.item_id = i.id " +
 63	 "WHERE bi.bill_id = ?";
 64	
 65	 try (Connection conn = DBUtil.getInstance().getConnection()) {
 66	 Map<String, Object> billDetails = new HashMap<>();
 67	
 68	 // Get bill information
 69	 try (PreparedStatement billStmt = conn.prepareStatement(billSql)) {
 70	 billStmt.setInt(1, billId);
 71	 ResultSet billRs = billStmt.executeQuery();
 72	
 73	 if (billRs.next()) {
 74	 billDetails.put("id", billRs.getInt("id"));
 75	 billDetails.put("billDate", billRs.getDate("bill_date"));
 76	 billDetails.put("total", billRs.getDouble("total_amount"));
 77	 billDetails.put("customerAccountNumber", billRs.getString("customer_account_number"));
 78	 billDetails.put("customerName", billRs.getString("full_name"));
 79	 billDetails.put("customerAddress", billRs.getString("address"));
 80	 billDetails.put("customerTelephone", billRs.getString("telephone"));
 81	 } else {
 82	 return null; // Bill not found
 83	 }
 84	 }
 85	
 86	 // Get bill items
 87	 List<Map<String, Object>> items = new ArrayList<>();
 88	 try (PreparedStatement itemsStmt = conn.prepareStatement(itemsSql)) {
 89	 itemsStmt.setInt(1, billId);
 90	 ResultSet itemsRs = itemsStmt.executeQuery();
 91	
 92	 while (itemsRs.next()) {
 93	 Map<String, Object> item = new HashMap<>();
 94	 item.put("itemId", itemsRs.getInt("item_id"));
 95	 item.put("itemName", itemsRs.getString("item_name"));
 96	 item.put("quantity", itemsRs.getInt("quantity"));
 97	 item.put("unitPrice", itemsRs.getDouble("unit_price"));
 98	 item.put("total", itemsRs.getInt("quantity") * itemsRs.getDouble("unit_price"));
 99	 items.add(item);
 100	 }
 101	 }
 102	
 103	 billDetails.put("items", items);
 104	 return billDetails;
 105	
 106	 } catch (SQLException e) {
 107	 e.printStackTrace();
 108	 return null;
 109	 }
 110	 }
 111	}
