ght: 600;\n transition: background-color 0.3s, transform 0.2s;\n}\n.manage-items .btn-primary:hover {\n transform: translateY(-2px);\n}\n.manage-items .spinner-border {\n display: none;\n margin-right: 0.5rem;\n}\n.manage-items .table-responsive {\n margin-top: 2rem;\n}\n.manage-items .table {\n background-color: #fff;\n border-radius: 0.5rem;\n overflow: hidden;\n}\n.manage-items .table th {\n cursor: pointer;\n user-select: none;\n color: #0d6efd;\n transition: background-color 0.3s;\n}\n.manage-items .table th:hover {\n background-color: #e9ecef;\n}\n.manage-items .btn-sm {\n padding: 0.25rem 0.5rem;\n font-size: 0.875rem;\n}\n.manage-items .btn-outline-primary, .manage-items .btn-outline-danger {\n transition: background-color 0.3s, color 0.3s;\n}\n.manage-items .btn-outline-primary:hover i, .manage-items .btn-outline-danger:hover i {\n color: #fff;\n}", "new_str_start_line_number": 140, "new_str_end_line_number": 204}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Aha! I found the issue! The CSS file has specific styles for `.manage-customers` but there are no corresponding styles for `.manage-items`. This is causing the visual differences you're seeing. Let me add the same styles for the manage-items section:
