 3	import com.example.pahanaedubackend.model.BillItem;
 4	import com.example.pahanaedubackend.service.BillService;
 5	import com.fasterxml.jackson.core.type.TypeReference;
 6	import com.fasterxml.jackson.databind.JsonNode;
 7	import com.fasterxml.jackson.databind.ObjectMapper;
 8	
 9	import javax.servlet.annotation.WebServlet;
 10	import javax.servlet.http.HttpServlet;
 11	import javax.servlet.http.HttpServletRequest;
 12	import javax.servlet.http.HttpServletResponse;
 13	import javax.servlet.http.HttpSession;
 14	import java.io.IOException;
 15	import java.util.List;
 16	
 17	@WebServlet("/bills-create")
 18	public class CreateBillServlet extends HttpServlet {
 19	 private final BillService billService = new BillService();
 20	 private final ObjectMapper mapper = new ObjectMapper();
 21	
 22	 @Override
 23	 protected void doPost(HttpServletRequest request, HttpServletResponse response)
 24	 throws IOException {
 25	
 26	 response.setContentType("application/json");
 27	 response.setCharacterEncoding("UTF-8");
 28	
 29	 HttpSession session = request.getSession(false);
 30	 if (session == null || session.getAttribute("admin") == null) {
 31	 response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
 32	 response.getWriter().write("{\"success\":false,\"message\":\"Unauthorized: Admin login required\"}");
 33	 return;
 34	 }
 35	
 36	 try {
 37	 // Parse JSON request body
 38	 JsonNode jsonNode = mapper.readTree(request.getInputStream());
 39	 String customerAccountNumber = jsonNode.get("customerAccountNumber").asText();
 40	 List<BillItem> items = mapper.convertValue(jsonNode.get("items"),
 41	 mapper.getTypeFactory().constructCollectionType(List.class, BillItem.class));
 42	
 43	 // Call service
 44	 int billId = billService.createBill(customerAccountNumber, items);
 45	
 46	 if (billId > 0) {
 47	 response.getWriter().write("{\"success\":true,\"message\":\"Bill created and stock updated\",\"billId\":" + billId + "}");
 48	 } else {
 49	 response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
 50	 response.getWriter().write("{\"success\":false,\"message\":\"Insufficient stock or error occurred\"}");
 51	 }
