 141	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 142	
 143	 stmt.setInt(1, newStock);
 144	 stmt.setInt(2, itemId);
 145	
 146	 int rowsUpdated = stmt.executeUpdate();
 147	 return rowsUpdated > 0;
 148	
 149	 } catch (SQLException e) {
 150	 e.printStackTrace();
 151	 }
 152	
 153	 return false;
