 16	@WebServlet("/customers")
 17	public class GetAllCustomersServlet extends HttpServlet {
 18	 private final CustomerService customerService = new CustomerService();
 19	
 20	 @Override
 21	 protected void doGet(HttpServletRequest request, HttpServletResponse response)
 22	 throws ServletException, IOException {
 23	
 24	 response.setContentType("application/json");
 25	 response.setCharacterEncoding("UTF-8");
 26	
 27	 HttpSession session = request.getSession(false);
 28	 if (session == null || session.getAttribute("admin") == null) {
 29	 response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
 30	 response.getWriter().write("{\"success\":false,\"message\":\"Unauthorized: Admin login required\"}");
 31	 return;
 32	 }
 33	
 34	 List<Customer> customers = customerService.getAllCustomers();
 35	 ObjectMapper mapper = new ObjectMapper();
 36	 mapper.writeValue(response.getWriter(), customers);
 37	 }
 38	}
