 11	public class AdminDAO {
 12	 public boolean addAdmin(Admin admin) {
 13	 String sql = "INSERT INTO admin (username, password, full_name, email) VALUES (?, ?, ?, ?)";
 14	
 15	 try (Connection conn = DBUtil.getInstance().getConnection();
 16	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 17	
 18	 stmt.setString(1, admin.getUsername());
 19	 stmt.setString(2, admin.getPassword()); // already hashed
 20	 stmt.setString(3, admin.getFullName());
 21	 stmt.setString(4, admin.getEmail());
 22	
 23	 return stmt.executeUpdate() > 0;
 24	 } catch (SQLException e) {
 25	 e.printStackTrace();
 26	 return false;
 27	 }
 28	 }
