 30	 billStmt.executeUpdate();
 31	
 32	 ResultSet generatedKeys = billStmt.getGeneratedKeys();
 33	 if (generatedKeys.next()) {
 34	 int billId = generatedKeys.getInt(1);
 35	
 36	 try (PreparedStatement itemStmt = conn.prepareStatement(billItemSql)) {
 37	 for (BillItem item : billItems) {
 38	 itemStmt.setInt(1, billId);
 39	 itemStmt.setInt(2, item.getItemId());
 40	 itemStmt.setInt(3, item.getQuantity());
 41	 itemStmt.setDouble(4, item.getPrice());
 42	 itemStmt.addBatch();
 43	 }
 44	 itemStmt.executeBatch();
 45	 }
 46	
 47	 conn.commit();
 48	 return billId;
 49	 }
 50	 } catch (SQLException e) {
 51	 conn.rollback();
 52	 e.printStackTrace();
 53	 }
 54	 } catch (SQLException e) {
 55	 e.printStackTrace();
 56	 }
 57	
 58	 return -1;
 59	 }
