checkPassword(plainPassword, admin.getPassword())) {\n return admin;\n }\n return null;\n } catch (Exception e) {\n System.err.println(\"Failed to login admin: \" + e.getMessage());\n e.printStackTrace();\n return null;\n }\n }\n \n /**\n * Check if admin exists by username\n * @param username Admin username\n * @return true if exists, false otherwise\n */\n public boolean existsByUsername(String username) {\n try {\n Admin admin = adminDAO.getAdminByUsername(username);\n return admin != null;\n } catch (Exception e) {\n System.err.println(\"Failed to check admin existence: \" + e.getMessage());\n e.printStackTrace();\n return false;\n }\n }\n \n /**\n * Get admin by username\n * @param username Admin username\n * @return Admin object if found, null otherwise\n */\n public Admin getAdminByUsername(String username) {\n try {\n return adminDAO.getAdminByUsername(username);\n } catch (Exception e) {\n System.err.println(\"Failed to get admin by username: \" + e.getMessage());\n e.printStackTrace();\n return null;\n }\n }\n \n /**\n * Validate admin credentials\n * @param username Admin username\n * @param plainPassword Plain text password\n * @return true if credentials are valid, false otherwise\n */\n public boolean validateCredentials(String username, String plainPassword) {\n try {\n Admin admin = adminDAO.getAdminByUsername(username);\n return admin != null && PasswordUtil.checkPassword(plainPassword, admin.getPassword());\n } catch (Exception e) {\n System.err.println(\"Failed to validate admin credentials: \" + e.getMessage());\n e.printStackTrace();\n return false;\n }\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Now let me create the implementation classes directly in the service package. I'll create enhanced versions of the existing service classes with "Impl" suffix:
