 15	public class BillService {
 16	 private final BillDAO billDAO = new BillDAO();
 17	 private final ItemDAO itemDAO = new ItemDAO();
 18	
 19	 public int createBill(String customerAccountNumber, List<BillItem> billItems) {
 20	 double total = 0.0;
 21	 List<BillItem> validItems = new ArrayList<>();
 22	
 23	 for (BillItem billItem : billItems) {
 24	 Item item = itemDAO.getItemById(billItem.getItemId());
 25	 if (item != null && item.getQuantity() >= billItem.getQuantity()) {
 26	 double itemTotal = item.getPrice() * billItem.getQuantity();
 27	 total += itemTotal;
 28	
 29	 billItem.setPrice(item.getPrice());
 30	 validItems.add(billItem);
 31	
 32	 // update item stock
 33	 itemDAO.updateStock(item.getId(), item.getQuantity() - billItem.getQuantity());
 34	 } else {
 35	 return -1; // insufficient stock or invalid item
 36	 }
 37	 }
 38	
 39	 Bill bill = new Bill();
 40	 bill.setBillDate(new Date());
 41	 bill.setTotal(total);
 42	 bill.setCustomerAccountNumber(customerAccountNumber);
 43	
 44	 return billDAO.createBill(bill, validItems);
 45	 }
 46	
 47	 public Map<String, Object> getBillDetails(int billId) {
