inDAO getAdminDAO() {\n if (adminDAO == null) {\n adminDAO = new AdminDAO();\n }\n return adminDAO;\n }\n \n /**\n * Get BillDAO instance\n * @return BillDAO instance\n */\n public BillDAO getBillDAO() {\n if (billDAO == null) {\n billDAO = new BillDAO();\n }\n return billDAO;\n }\n \n /**\n * Get CustomerDAO instance\n * @return CustomerDAO instance\n */\n public CustomerDAO getCustomerDAO() {\n if (customerDAO == null) {\n customerDAO = new CustomerDAO();\n }\n return customerDAO;\n }\n \n /**\n * Get ItemDAO instance\n * @return ItemDAO instance\n */\n public ItemDAO getItemDAO() {\n if (itemDAO == null) {\n itemDAO = new ItemDAO();\n }\n return itemDAO;\n }\n \n /**\n * Get UserDAO instance\n * @return UserDAO instance\n */\n public UserDAO getUserDAO() {\n if (userDAO == null) {\n userDAO = new UserDAO();\n }\n return userDAO;\n }\n \n /**\n * Reset all DAO instances (useful for testing)\n */\n public void resetDAOs() {\n adminDAO = null;\n billDAO = null;\n customerDAO = null;\n itemDAO = null;\n userDAO = null;\n }\n}", "old_str_start_line_number_1": 1, "old_str_end_line_number_1": 1}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Based on my analysis of your pahana-edu-back-end codebase, I can see several opportunities to implement design patterns using existing dependencies. Let me create a detailed plan to add suitable design patterns that will improve code maintainability, flexibility, and follow best practices.

## Analysis and Plan

Your current architecture shows:
- **Existing patterns**: Singleton (DBUtil), some Service Layer pattern
