n CustomerDAO instance\n */\n public CustomerDAO getCustomerDAO() {\n if (customerDAO == null) {\n customerDAO = new CustomerDAO();\n }\n return customerDAO;\n }\n \n /**\n * Get ItemDAO instance\n * @return ItemDAO instance\n */\n public ItemDAO getItemDAO() {\n if (itemDAO == null) {\n itemDAO = new ItemDAO();\n }\n return itemDAO;\n }\n \n /**\n * Get UserDAO instance\n * @return UserDAO instance\n */\n public UserDAO getUserDAO() {\n if (userDAO == null) {\n userDAO = new UserDAO();\n }\n return userDAO;\n }\n \n /**\n * Reset all DAO instances (useful for testing)\n */\n public void resetDAOs() {\n adminDAO = null;\n billDAO = null;\n customerDAO = null;\n itemDAO = null;\n userDAO = null;\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"File not found: pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/factory/DAOFactory.java","is_error":true,"request_id":"","tool_use_id":"toolu_01C22k4f7pDfHPFYGNtthZqp"}},{"id":2,"type":4,"ide_state_node":{"workspaceFolders":[{"repositoryRoot":"D:/projects/pahana-edu-management-system","folderRoot":"D:/projects/pahana-edu-management-system"}],"workspaceFoldersUnchanged":false}}],"timestamp":"2025-07-26T10:37:59.665Z","response_text":"","workspace_file_chunks":[]},{"status":"success","request_id":"156c7f2c-003b-4913-af36-1c6eeb04666d","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01NaJerk5yAk44AfmWhaiwUz","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/strategy/AuthenticationStrategy.java", "file_content": "package com.example.pahanaedubackend.strategy;\n\nimport javax.servlet.http.HttpServletRequest;\nimport javax.servlet.http.HttpServletResponse;\n\n/**\n * Strategy Pattern Interface for Authentication\n * Allows different authentication mechanisms\n */\npublic interface AuthenticationStrategy {\n \n /**\n * Authenticate the request\n * @param request HTTP request\n * @param response HTTP response\n * @return true if authenticated, false otherwise\n */\n boolean authenticate(HttpServletRequest request, HttpServletResponse response);\n \n /**\n * Get authentication error message\n * @return error message\n */\n String getErrorMessage();\n \n /**\n * Get HTTP status code for authentication failure\n * @return HTTP status code\n */\n int getErrorStatusCode();\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"File saved. Saved file {pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/factory/DAOFactory.java}","is_error":false,"request_id":"","tool_use_id":"toolu_01SBrMeR4xai3dDUXLK8Erko"}},{"id":2,"type":4,"ide_state_node":{"workspaceFolders":[{"repositoryRoot":"D:/projects/pahana-edu-management-system","folderRoot":"D:/projects/pahana-edu-management-system"}],"workspaceFoldersUnchanged":false}}],"timestamp":"2025-07-26T10:38:15.843Z","response_text":"","workspace_file_chunks":[]},{"status":"success","request_id":"7621489c-31b1-424a-99c6-81cce98bacf3","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_019tnA6NqiH63u8gjoZPxfXV","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/strategy/AdminSessionAuthenticationStrategy.java", "file_content": "package com.example.pahanaedubackend.strategy;\n\nimport javax.servlet.http.HttpServletRequest;\nimport javax.servlet.http.HttpServletResponse;\nimport javax.servlet.http.HttpSession;\n\n/**\n * Strategy Pattern Implementation for Admin Session Authentication\n */\npublic class AdminSessionAuthenticationStrategy implements AuthenticationStrategy {\n \n private static final String ERROR_MESSAGE = \"Unauthorized: Admin login required\";\n private static final int ERROR_STATUS_CODE = HttpServletResponse.SC_UNAUTHORIZED;\n \n @Override\n public boolean authenticate(HttpServletRequest request, HttpServletResponse response) {\n HttpSession session = request.getSession(false);\n return session != null && session.getAttribute(\"admin\") != null;\n }\n \n @Override\n public String getErrorMessage() {\n return ERROR_MESSAGE;\n }\n \n @Override\n public int getErrorStatusCode() {\n return ERROR_STATUS_CODE;\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"File saved. Saved file {pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/strategy/AuthenticationStrategy.java}","is_error":false,"request_id":"","tool_use_id":"toolu_01NaJerk5yAk44AfmWhaiwUz"}},{"id":2,"type":4,"ide_state_node":{"workspaceFolders":[{"repositoryRoot":"D:/projects/pahana-edu-management-system","folderRoot":"D:/projects/pahana-edu-management-system"}],"workspaceFoldersUnchanged":false}}],"timestamp":"2025-07-26T10:38:21.949Z","response_text":"","workspace_file_chunks":[]},{"status":"success","request_id":"23b79b68-89e8-4e87-b50a-513ca3624dbe","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_0195PjV8eHRajddgXtShcvbn","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/strategy/ResponseStrategy.java", "file_content": "package com.example.pahanaedubackend.strategy;\n\nimport javax.servlet.http.HttpServletResponse;\nimport java.io.IOException;\n\n/**\n * Strategy Pattern Interface for Response Handling\n * Allows different response formatting strategies\n */\npublic interface ResponseStrategy {\n \n /**\n * Send success response\n * @param response HTTP response\n * @param data response data\n * @param message success message\n * @throws IOException if writing response fails\n */\n void sendSuccessResponse(HttpServletResponse response, Object data, String message) throws IOException;\n \n /**\n * Send error response\n * @param response HTTP response\n * @param statusCode HTTP status code\n * @param message error message\n * @throws IOException if writing response fails\n */\n void sendErrorResponse(HttpServletResponse response, int statusCode, String message) throws IOException;\n \n /**\n * Send data response (for GET requests)\n * @param response HTTP response\n * @param data response data\n * @throws IOException if writing response fails\n */\n void sendDataResponse(HttpServletResponse response, Object data) throws IOException;\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"File saved. Saved file {pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/strategy/AdminSessionAuthenticationStrategy.java}","is_error":false,"request_id":"","tool_use_id":"toolu_019tnA6NqiH63u8gjoZPxfXV"}},{"id":2,"type":4,"ide_state_node":{"workspaceFolders":[{"repositoryRoot":"D:/projects/pahana-edu-management-system","folderRoot":"D:/projects/pahana-edu-management-system"}],"workspaceFoldersUnchanged":false}}],"timestamp":"2025-07-26T10:38:28.265Z","response_text":"","workspace_file_chunks":[]},{"status":"success","request_id":"09d0b64a-0f6e-40a4-b164-95c87b4ee2ad","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_019WaNcEc3iRPZAMpYcac9yt","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/strategy/JsonResponseStrategy.java", "file_content": "package com.example.pahanaedubackend.strategy;\n\nimport com.fasterxml.jackson.databind.ObjectMapper;\n\nimport javax.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport java.util.HashMap;\nimport java.util.Map;\n\n/**\n * Strategy Pattern Implementation for JSON Response Handling\n */\npublic class JsonResponseStrategy implements ResponseStrategy {\n \n private final ObjectMapper objectMapper;\n \n public JsonResponseStrategy() {\n this.objectMapper = new ObjectMapper();\n }\n \n @Override\n public void sendSuccessResponse(HttpServletResponse response, Object data, String message) throws IOException {\n response.setContentType(\"application/json\");\n response.setCharacterEncoding(\"UTF-8\");\n response.setStatus(HttpServletResponse.SC_OK);\n \n Map<String, Object> result = new HashMap<>();\n result.put(\"success\", true);\n result.put(\"message\", message);\n if (data != null) {\n result.put(\"data\", data);\n }\n \n objectMapper.writeValue(response.getWriter(), result);\n }\n \n @Override\n public void sendErrorResponse(HttpServletResponse response, int statusCode, String message) throws IOException {\n response.setContentType(\"application/json\");\n response.setCharacterEncoding(\"UTF-8\");\n response.setStatus(statusCode);\n \n Map<String, Object> result = new HashMap<>();\n result.put(\"success\", false);\n result.put(\"message\", message);\n \n objectMapper.writeValue(response.getWriter(), result);\n }\n \n @Override\n public void sendDataResponse(HttpServletResponse response, Object data) throws IOException {\n response.setContentType(\"application/json\");\n response.setCharacterEncoding(\"UTF-8\");\n response.setStatus(HttpServletResponse.SC_OK);\n \n objectMapper.writeValue(response.getWriter(), data);\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"File saved. Saved file {pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/strategy/ResponseStrategy.java}","is_error":false,"request_id":"","tool_use_id":"toolu_0195PjV8eHRajddgXtShcvbn"}},{"id":2,"type":4,"ide_state_node":{"workspaceFolders":[{"repositoryRoot":"D:/projects/pahana-edu-management-system","folderRoot":"D:/projects/pahana-edu-management-system"}],"workspaceFoldersUnchanged":false}}],"timestamp":"2025-07-26T10:38:35.182Z","response_text":"","workspace_file_chunks":[]},{"status":"success","request_id":"54d973e6-6e0a-45bb-88d4-3d38059e5262","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01RYsHvJuHNLfPQYwqAMpsZ5","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/template/BaseServlet.java", "file_content": "package com.example.pahanaedubackend.template;\n\nimport com.example.pahanaedubackend.strategy.AuthenticationStrategy;\nimport com.example.pahanaedubackend.strategy.ResponseStrategy;\nimport com.example.pahanaedubackend.strategy.AdminSessionAuthenticationStrategy;\nimport com.example.pahanaedubackend.strategy.JsonResponseStrategy;\n\nimport javax.servlet.ServletException;\nimport javax.servlet.http.HttpServlet;\nimport javax.servlet.http.HttpServletRequest;\nimport javax.servlet.http.HttpServletResponse;\nimport java.io.IOException;\n\n/**\n * Template Method Pattern Implementation for Base Servlet\n * Provides common servlet functionality and structure\n */\npublic abstract class BaseServlet extends HttpServlet {\n \n protected AuthenticationStrategy authStrategy;\n protected ResponseStrategy responseStrategy;\n \n public BaseServlet() {\n this.authStrategy = new AdminSessionAuthenticationStrategy();\n this.responseStrategy = new JsonResponseStrategy();\n }\n \n public BaseServlet(AuthenticationStrategy authStrategy, ResponseStrategy responseStrategy) {\n this.authStrategy = authStrategy;\n this.responseStrategy = responseStrategy;\n }\n \n @Override\n protected final void doGet(HttpServletRequest request, HttpServletResponse response) \n throws ServletException, IOException {\n processRequest(request, response, \"GET\");\n }\n \n @Override\n protected final void doPost(HttpServletRequest request, HttpServletResponse response) \n throws ServletException, IOException {\n processRequest(request, response, \"POST\");\n }\n \n @Override\n protected final void doPut(HttpServletRequest request, HttpServletResponse response) \n throws ServletException, IOException {\n processRequest(request, response, \"PUT\");\n }\n \n @Override\n protected final void doDelete(HttpServletRequest request, HttpServletResponse response) \n throws ServletException, IOException {\n processRequest(request, response, \"DELETE\");\n }\n \n /**\n * Template method that defines the request processing algorithm\n */\n private void processRequest(HttpServletRequest request, HttpServletResponse response, String method) \n throws ServletException, IOException {\n \n try {\n // Step 1: Authentication (if required)\n if (requiresAuthentication() && !authenticate(request, response)) {\n return; // Authentication failed, response already sent\n }\n \n // Step 2: Process the specific request based on HTTP method\n switch (method) {\n case \"GET\":\n handleGet(request, response);\n break;\n case \"POST\":\n handlePost(request, response);\n break;\n case \"PUT\":\n handlePut(request, response);\n break;\n case \"DELETE\":\n handleDelete(request, response);\n break;\n default:\n responseStrategy.sendErrorResponse(response, \n HttpServletResponse.SC_METHOD_NOT_ALLOWED, \n \"Method not allowed\");\n }\n \n } catch (Exception e) {\n handleException(request, response, e);\n }\n }\n \n /**\n * Authenticate the request using the configured strategy\n */\n private boolean authenticate(HttpServletRequest request, HttpServletResponse response) throws IOException {\n if (authStrategy.authenticate(request, response)) {\n return true;\n } else {\n responseStrategy.sendErrorResponse(response, \n authStrategy.getErrorStatusCode(), \n authStrategy.getErrorMessage());\n return false;\n }\n }\n \n // Abstract methods to be implemented by subclasses\n protected abstract boolean requiresAuthentication();\n \n protected void handleGet(HttpServletRequest request, HttpServletResponse response) \n throws ServletException, IOException {\n responseStrategy.sendErrorResponse(response, \n HttpServletResponse.SC_METHOD_NOT_ALLOWED, \n \"GET method not supported\");\n }\n \n protected void handlePost(HttpServletRequest request, HttpServletResponse response) \n throws ServletException, IOException {\n responseStrategy.sendErrorResponse(response, \n HttpServletResponse.SC_METHOD_NOT_ALLOWED, \n \"POST method not supported\");\n }\n \n protected void handlePut(HttpServletRequest request, HttpServletResponse response) \n throws ServletException, IOException {\n responseStrategy.sendErrorResponse(response, \n HttpServletResponse.SC_METHOD_NOT_ALLOWED, \n \"PUT method not supported\");\n }\n \n protected void handleDelete(HttpServletRequest request, HttpServletResponse response) \n throws ServletException, IOException {\n responseStrategy.sendErrorResponse(response, \n HttpServletResponse.SC_METHOD_NOT_ALLOWED, \n \"DELETE method not supported\");\n }\n \n /**\n * Handle exceptions in a consistent way\n */\n protected void handleException(HttpServletRequest request, HttpServletResponse response, Exception e) \n throws IOException {\n e.printStackTrace();\n responseStrategy.sendErrorResponse(response, \n HttpServletResponse.SC_INTERNAL_SERVER_ERROR, \n \"Internal server error occurred\");\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"File saved. Saved file {pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/strategy/JsonResponseStrategy.java}","is_error":false,"request_id":"","tool_use_id":"toolu_019WaNcEc3iRPZAMpYcac9yt"}},{"id":2,"type":4,"ide_state_node":{"workspaceFolders":[{"repositoryRoot":"D:/projects/pahana-edu-management-system","folderRoot":"D:/projects/pahana-edu-management-system"}],"workspaceFoldersUnchanged":false}}],"timestamp":"2025-07-26T10:38:43.208Z","response_text":"","workspace_file_chunks":[]},{"status":"success","request_id":"540f13c9-9cdd-4c42-b908-cfa6131f9603","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01CcXbC3HNbtiFneHgq6PwnU","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/builder/ApiResponse.java", "file_content": "package com.example.pahanaedubackend.builder;\n\nimport java.util.HashMap;\nimport java.util.Map;\n\n/**\n * Builder Pattern Implementation for API Response\n * Provides flexible response object construction\n */\npublic class ApiResponse {\n \n private boolean success;\n private String message;\n private Object data;\n private Map<String, Object> metadata;\n private int statusCode;\n \n private ApiResponse(Builder builder) {\n this.success = builder.success;\n this.message = builder.message;\n this.data = builder.data;\n this.metadata = builder.metadata;\n this.statusCode = builder.statusCode;\n }\n \n // Getters\n public boolean isSuccess() {\n return success;\n }\n \n public String getMessage() {\n return message;\n }\n \n public Object getData() {\n return data;\n }\n \n public Map<String, Object> getMetadata() {\n return metadata;\n }\n \n public int getStatusCode() {\n return statusCode;\n }\n \n /**\n * Convert to Map for JSON serialization\n */\n public Map<String, Object> toMap() {\n Map<String, Object> result = new HashMap<>();\n result.put(\"success\", success);\n result.put(\"message\", message);\n \n if (data != null) {\n result.put(\"data\", data);\n }\n \n if (metadata != null && !metadata.isEmpty()) {\n result.put(\"metadata\", metadata);\n }\n \n return result;\n }\n \n /**\n * Builder class for ApiResponse\n */\n public static class Builder {\n private boolean success;\n private String message;\n private Object data;\n private Map<String, Object> metadata;\n private int statusCode = 200;\n \n public Builder success(boolean success) {\n this.success = success;\n return this;\n }\n \n public Builder message(String message) {\n this.message = message;\n return this;\n }\n \n public Builder data(Object data) {\n this.data = data;\n return this;\n }\n \n public Builder statusCode(int statusCode) {\n this.statusCode = statusCode;\n return this;\n }\n \n public Builder addMetadata(String key, Object value) {\n if (this.metadata == null) {\n this.metadata = new HashMap<>();\n }\n this.metadata.put(key, value);\n return this;\n }\n \n public Builder metadata(Map<String, Object> metadata) {\n this.metadata = metadata;\n return this;\n }\n \n public ApiResponse build() {\n return new ApiResponse(this);\n }\n }\n \n // Static factory methods for common responses\n public static ApiResponse success(String message) {\n return new Builder()\n .success(true)\n .message(message)\n .build();\n }\n \n public static ApiResponse success(String message, Object data) {\n return new Builder()\n .success(true)\n .message(message)\n .data(data)\n .build();\n }\n \n public static ApiResponse error(String message) {\n return new Builder()\n .success(false)\n .message(message)\n .statusCode(400)\n .build();\n }\n \n public static ApiResponse error(String message, int statusCode) {\n return new Builder()\n .success(false)\n .message(message)\n .statusCode(statusCode)\n .build();\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"File saved. Saved file {pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/template/BaseServlet.java}","is_error":false,"request_id":"","tool_use_id":"toolu_01RYsHvJuHNLfPQYwqAMpsZ5"}},{"id":2,"type":4,"ide_state_node":{"workspaceFolders":[{"repositoryRoot":"D:/projects/pahana-edu-management-system","folderRoot":"D:/projects/pahana-edu-management-system"}],"workspaceFoldersUnchanged":false}}],"timestamp":"2025-07-26T10:39:00.290Z","response_text":"","workspace_file_chunks":[]},{"status":"success","request_id":"2f4c0082-c387-4db1-8171-98fc0790b38a","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01C8UyZCTXiTAuWQZedftAj9","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/observer/AuditEvent.java", "file_content": "package com.example.pahanaedubackend.observer;\n\nimport java.util.Date;\nimport java.util.HashMap;\nimport java.util.Map;\n\n/**\n * Event class for Observer Pattern Implementation\n * Represents an audit event in the system\n */\npublic class AuditEvent {\n \n public enum EventType {\n USER_LOGIN,\n USER_LOGOUT,\n CUSTOMER_CREATED,\n CUSTOMER_UPDATED,\n CUSTOMER_DELETED,\n ITEM_CREATED,\n ITEM_UPDATED,\n ITEM_DELETED,\n BILL_CREATED,\n ADMIN_REGISTERED,\n AUTHENTICATION_FAILED,\n SYSTEM_ERROR\n }\n \n private final EventType eventType;\n private final String userId;\n private final Date timestamp;\n private final String description;\n private final Map<String, Object> details;\n \n public AuditEvent(EventType eventType, String userId, String description) {\n this.eventType = eventType;\n this.userId = userId;\n this.description = description;\n this.timestamp = new Date();\n this.details = new HashMap<>();\n }\n \n public AuditEvent(EventType eventType, String userId, String description, Map<String, Object> details) {\n this.eventType = eventType;\n this.userId = userId;\n this.description = description;\n this.timestamp = new Date();\n this.details = details != null ? new HashMap<>(details) : new HashMap<>();\n }\n \n // Getters\n public EventType getEventType() {\n return eventType;\n }\n \n public String getUserId() {\n return userId;\n }\n \n public Date getTimestamp() {\n return timestamp;\n }\n \n public String getDescription() {\n return description;\n }\n \n public Map<String, Object> getDetails() {\n return new HashMap<>(details);\n }\n \n public void addDetail(String key, Object value) {\n details.put(key, value);\n }\n \n @Override\n public String toString() {\n return String.format(\"AuditEvent{eventType=%s, userId='%s', timestamp=%s, description='%s', details=%s}\",\n eventType, userId, timestamp, description, details);\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content