ing, Object> details = new HashMap<>();\n details.put(\"itemId\", item.getId());\n details.put(\"itemName\", item.getName());\n details.put(\"price\", item.getPrice());\n details.put(\"quantity\", item.getQuantity());\n \n AuditEvent event = new AuditEvent(AuditEvent.EventType.ITEM_UPDATED, userId, \n \"Item updated successfully\", details);\n auditManager.notifyObservers(event);\n }\n return result;\n } catch (Exception e) {\n auditManager.logEvent(AuditEvent.EventType.SYSTEM_ERROR, userId, \n \"Failed to update item: \" + e.getMessage());\n return false;\n }\n }\n\n public boolean isItemUsedInBills(int itemId) {\n return itemDAO.isItemUsedInBills(itemId);\n }\n\n public boolean deleteItem(int itemId) {\n return deleteItem(itemId, \"SYSTEM\");\n }\n \n public boolean deleteItem(int itemId, String userId) {\n try {\n boolean result = itemDAO.deleteItem(itemId);\n if (result) {\n Map<String, Object> details = new HashMap<>();\n details.put(\"itemId\", itemId);\n \n AuditEvent event = new AuditEvent(AuditEvent.EventType.ITEM_DELETED, userId, \n \"Item deleted successfully\", details);\n auditManager.notifyObservers(event);\n }\n return result;\n } catch (Exception e) {\n auditManager.logEvent(AuditEvent.EventType.SYSTEM_ERROR, userId, \n \"Failed to delete item: \" + e.getMessage());\n return false;\n }\n }", "old_str_start_line_number_1": 22, "old_str_end_line_number_1": 39}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":""},{"id":3,"type":2,"content":""},{"id":4,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"Note: Path was automatically corrected from 'pahana-edu-back-end/src/main/java/com/example/pahanaedubackend/service/ItemService.java' to 'D:\projects\pahana-edu-management-system\pahana-edu-back-end\src\main\java\com\example\pahanaedubackend\service\ItemService.java'.

