 39	 public int createBill(String customerAccountNumber, List<BillItem> billItems) {
 40	 try {
 41	 // Validate input parameters
 42	 if (customerAccountNumber == null || customerAccountNumber.trim().isEmpty()) {
 43	 System.err.println("Invalid customer account number");
 44	 return -1;
 45	 }
 46	 
 47	 if (billItems == null || billItems.isEmpty()) {
 48	 System.err.println("Bill items cannot be empty");
 49	 return -1;
 50	 }
 51	 
 52	 double total = 0.0;
 53	 List<BillItem> validItems = new ArrayList<>();
 54	
 55	 // Validate and process each bill item
 56	 for (BillItem billItem : billItems) {
 57	 if (billItem == null || billItem.getItemId() <= 0 || billItem.getQuantity() <= 0) {
 58	 System.err.println("Invalid bill item data");
 59	 return -1;
 60	 }
 61	 
 62	 Item item = itemDAO.getItemById(billItem.getItemId());
 63	 if (item == null) {
 64	 System.err.println("Item not found with ID: " + billItem.getItemId());
 65	 return -1;
 66	 }
 67	 
 68	 if (item.getQuantity() < billItem.getQuantity()) {
 69	 System.err.println("Insufficient stock for item: " + item.getName() + 
 70	 ". Available: " + item.getQuantity() + ", Requested: " + billItem.getQuantity());
 71	 return -1;
 72	 }
 73	 
 74	 double itemTotal = item.getPrice() * billItem.getQuantity();
 75	 total += itemTotal;
 76	
 77	 billItem.setPrice(item.getPrice());
 78	 validItems.add(billItem);
 79	
 80	 // Update item stock
 81	 boolean stockUpdated = itemDAO.updateStock(item.getId(), item.getQuantity() - billItem.getQuantity());
 82	 if (!stockUpdated) {
 83	 System.err.println("Failed to update stock for item: " + item.getName());
 84	 return -1;
 85	 }
 86	 }
 87	
 88	 // Create bill object
 89	 Bill bill = new Bill();
 90	 bill.setBillDate(new Date());
 91	 bill.setTotal(total);
 92	 bill.setCustomerAccountNumber(customerAccountNumber);
 93	
 94	 return billDAO.createBill(bill, validItems);
