 1	package com.example.pahanaedubackend.controller;
 2	
 3	import com.example.pahanaedubackend.model.Customer;
 4	import com.example.pahanaedubackend.service.CustomerService;
 5	import com.example.pahanaedubackend.util.PasswordUtil;
 6	import com.fasterxml.jackson.databind.ObjectMapper;
 7	
 8	import javax.servlet.ServletException;
 9	import javax.servlet.annotation.WebServlet;
 10	import javax.servlet.http.HttpServlet;
 11	import javax.servlet.http.HttpServletRequest;
 12	import javax.servlet.http.HttpServletResponse;
 13	import javax.servlet.http.HttpSession;
 14	import java.io.IOException;
 15	import java.util.HashMap;
 16	import java.util.Map;
 17	
 18	@WebServlet("/register-customer")
 19	public class CustomerRegisterServlet extends HttpServlet {
 20	 private final CustomerService customerService = new CustomerService();
 21	
 22	 @Override
 23	 protected void doPost(HttpServletRequest request, HttpServletResponse response)
 24	 throws ServletException, IOException {
 25	
 26	
 27	 response.setContentType("application/json");
 28	 response.setCharacterEncoding("UTF-8");
 29	
 30	 HttpSession session = request.getSession(false);
 31	 if (session == null || session.getAttribute("admin") == null) {
 32	 response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
 33	 response.getWriter().write("{\"success\":false, \"message\":\"Unauthorized: Admin login required\"}");
 34	 return;
 35	 }
 36	
 37	 ObjectMapper mapper = new ObjectMapper();
 38	 Map<String, Object> data = mapper.readValue(request.getInputStream(), Map.class);
 39	
 40	 Customer customer = new Customer();
 41	 customer.setAccountNumber((String) data.get("accountNumber"));
 42	 customer.setFullName((String) data.get("fullName"));
 43	 customer.setTelephone((String) data.get("telephone"));
 44	 customer.setAddress((String) data.get("address"));
 45	
 46	 // Handle unitsConsumed which can be either Integer or String
 47	 Object unitsConsumedObj = data.get("unitsConsumed");
 48	 int unitsConsumed;
 49	 if (unitsConsumedObj instanceof Integer) {
 50	 unitsConsumed = (Integer) unitsConsumedObj;
 51	 } else if (unitsConsumedObj instanceof String) {
 52	 unitsConsumed = Integer.parseInt((String) unitsConsumedObj);
 53	 } else {
 54	 throw new IllegalArgumentException("Invalid unitsConsumed value: " + unitsConsumedObj);
 55	 }
 56	 customer.setUnitsConsumed(unitsConsumed);
 57	
 58	 boolean success = customerService.registerCustomer(customer);
 59	
 60	 Map<String, Object> result = new HashMap<>();
 61	 result.put("success", success);
 62	 result.put("message", success ? "Customer registered successfully" : "Customer registration failed");
 63	
 64	 mapper.writeValue(response.getWriter(), result);
 65	 }
 66	}
