 18	/**
 19	 * Example of using Template Method Pattern with BaseServlet and Builder Pattern
 20	 * This demonstrates the new pattern-based approach for bill creation
 21	 */
 22	@WebServlet("/bills-new")
 23	public class CreateBillServletNew extends BaseServlet {
 24	 
 25	 private final BillService billService = new BillService();
 26	 private final ObjectMapper mapper = new ObjectMapper();
 27	 
 28	 @Override
 29	 protected boolean requiresAuthentication() {
 30	 return true; // This servlet requires admin authentication
 31	 }
 32	 
 33	 @Override
 34	 protected void handlePost(HttpServletRequest request, HttpServletResponse response) 
 35	 throws ServletException, IOException {
 36	 
 37	 try {
 38	 // Parse JSON request body
 39	 JsonNode jsonNode = mapper.readTree(request.getInputStream());
 40	 String customerAccountNumber = jsonNode.get("customerAccountNumber").asText();
 41	 List<BillItem> items = mapper.convertValue(jsonNode.get("items"),
 42	 mapper.getTypeFactory().constructCollectionType(List.class, BillItem.class));
 43	 
 44	 // Get user ID from session for audit purposes
 45	 HttpSession session = request.getSession(false);
 46	 String userId = "ADMIN"; // Default
 47	 if (session != null && session.getAttribute("admin") != null) {
 48	 // You could extract actual admin username here
 49	 userId = "ADMIN_USER";
 50	 }
 51	 
 52	 // Call service with user ID for audit trail
 53	 int billId = billService.createBill(customerAccountNumber, items, userId);
 54	 
 55	 if (billId > 0) {
 56	 // Using Builder Pattern for response
 57	 ApiResponse apiResponse = new ApiResponse.Builder()
 58	 .success(true)
 59	 .message("Bill created and stock updated")
 60	 .addMetadata("billId", billId)
 61	 .addMetadata("customerAccountNumber", customerAccountNumber)
 62	 .addMetadata("itemCount", items.size())
 63	 .build();
 64	 
 65	 responseStrategy.sendDataResponse(response, apiResponse.toMap());
 66	 
 67	 } else {
 68	 ApiResponse apiResponse = ApiResponse.error("Insufficient stock or error occurred", 
 69	 HttpServletResponse.SC_BAD_REQUEST);
 70	 
 71	 response.setStatus(apiResponse.getStatusCode());
 72	 responseStrategy.sendDataResponse(response, apiResponse.toMap());
 73	 }
