;\n }\n return itemDAO;\n }\n \n /**\n * Get BillDAO instance\n * Lazy initialization - creates instance only when needed\n * @return BillDAO instance\n */\n public BillDAO getBillDAO() {\n if (billDAO == null) {\n billDAO = new BillDAO();\n }\n return billDAO;\n }\n \n /**\n * Get AdminDAO instance\n * Lazy initialization - creates instance only when needed\n * @return AdminDAO instance\n */\n public AdminDAO getAdminDAO() {\n if (adminDAO == null) {\n adminDAO = new AdminDAO();\n }\n return adminDAO;\n }\n \n /**\n * Get UserDAO instance\n * Lazy initialization - creates instance only when needed\n * @return UserDAO instance\n */\n public UserDAO getUserDAO() {\n if (userDAO == null) {\n userDAO = new UserDAO();\n }\n return userDAO;\n }\n \n /**\n * Create DAO by type name\n * Factory method that creates DAO based on string parameter\n * @param daoType Type of DAO to create (\"customer\", \"item\", \"bill\", \"admin\", \"user\")\n * @return DAO instance or null if type not found\n */\n public Object createDAO(String daoType) {\n if (daoType == null || daoType.trim().isEmpty()) {\n return null;\n }\n \n switch (daoType.toLowerCase().trim()) {\n case \"customer\":\n return getCustomerDAO();\n case \"item\":\n return getItemDAO();\n case \"bill\":\n return getBillDAO();\n case \"admin\":\n return getAdminDAO();\n case \"user\":\n return getUserDAO();\n default:\n throw new IllegalArgumentException(\"Unknown DAO type: \" + daoType);\n }\n }\n \n /**\n * Reset all DAO instances\n * Useful for testing or when you need fresh instances\n */\n public void resetDAOs() {\n customerDAO = null;\n itemDAO = null;\n billDAO = null;\n adminDAO = null;\n userDAO = null;\n }\n \n /**\n * Check if DAO type is supported\n * @param daoType Type to check\n * @return true if supported, false otherwise\n */\n public boolean isDAOTypeSupported(String daoType) {\n if (daoType == null) return false;\n \n String type = daoType.toLowerCase().trim();\n return type.equals(\"customer\") || type.equals(\"item\") || \n type.equals(\"bill\") || type.equals(\"admin\") || type.equals(\"user\");\n }\n \n /**\n * Get all supported DAO types\n * @return Array of supported DAO type names\n */\n public String[] getSupportedDAOTypes() {\n return new String[]{\"customer\", \"item\", \"bill\", \"admin\", \"user\"};\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"I can see that you don't have a factory package yet, but I noticed from the DESIGN_PATTERNS_README.md that there should be a DAOFactory. Let me implement a comprehensive Factory design pattern for your project. I'll create multiple factory patterns:

