tance\n */\n public ItemService getItemService() {\n if (itemService == null) {\n itemService = new ItemService();\n }\n return itemService;\n }\n \n /**\n * Get BillService instance\n * Lazy initialization - creates instance only when needed\n * @return BillService instance\n */\n public BillService getBillService() {\n if (billService == null) {\n billService = new BillService();\n }\n return billService;\n }\n \n /**\n * Get AdminService instance\n * Lazy initialization - creates instance only when needed\n * @return AdminService instance\n */\n public AdminService getAdminService() {\n if (adminService == null) {\n adminService = new AdminService();\n }\n return adminService;\n }\n \n /**\n * Create Service by type name\n * Factory method that creates Service based on string parameter\n * @param serviceType Type of Service to create (\"customer\", \"item\", \"bill\", \"admin\")\n * @return Service instance or null if type not found\n */\n public Object createService(String serviceType) {\n if (serviceType == null || serviceType.trim().isEmpty()) {\n return null;\n }\n \n switch (serviceType.toLowerCase().trim()) {\n case \"customer\":\n return getCustomerService();\n case \"item\":\n return getItemService();\n case \"bill\":\n return getBillService();\n case \"admin\":\n return getAdminService();\n default:\n throw new IllegalArgumentException(\"Unknown Service type: \" + serviceType);\n }\n }\n \n /**\n * Reset all Service instances\n * Useful for testing or when you need fresh instances\n */\n public void resetServices() {\n customerService = null;\n itemService = null;\n billService = null;\n adminService = null;\n }\n \n /**\n * Check if Service type is supported\n * @param serviceType Type to check\n * @return true if supported, false otherwise\n */\n public boolean isServiceTypeSupported(String serviceType) {\n if (serviceType == null) return false;\n \n String type = serviceType.toLowerCase().trim();\n return type.equals(\"customer\") || type.equals(\"item\") || \n type.equals(\"bill\") || type.equals(\"admin\");\n }\n \n /**\n * Get all supported Service types\n * @return Array of supported Service type names\n */\n public String[] getSupportedServiceTypes() {\n return new String[]{\"customer\", \"item\", \"bill\", \"admin\"};\n }\n \n /**\n * Create service with dependency injection\n * Advanced factory method that can inject dependencies\n * @param serviceType Type of service to create\n * @param dependencies Optional dependencies to inject\n * @return Service instance with injected dependencies\n */\n public Object createServiceWithDependencies(String serviceType, Object... dependencies) {\n // For now, return standard service\n // This can be extended to support dependency injection\n return createService(serviceType);\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Now let me create a ServiceFactory:
