","workspace_file_chunks":[]},{"status":"success","request_id":"48a06ca3-599f-4a79-9d84-97a1636d30c6","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01C5qPjesdSXAMGzX3r4dFxo","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "src/main/java/com/example/pahanaedubackend/factory/ResponseFactory.java", "file_content": "package com.example.pahanaedubackend.factory;\n\nimport java.util.HashMap;\nimport java.util.Map;\n\n/**\n * Factory Pattern implementation for creating standardized API responses\n * Provides consistent response structure across all endpoints\n */\npublic class ResponseFactory {\n \n // Singleton instance\n private static ResponseFactory instance;\n \n // Private constructor to prevent direct instantiation\n private ResponseFactory() {\n // Private constructor for singleton\n }\n \n /**\n * Get singleton instance of ResponseFactory\n * @return ResponseFactory instance\n */\n public static synchronized ResponseFactory getInstance() {\n if (instance == null) {\n instance = new ResponseFactory();\n }\n return instance;\n }\n \n /**\n * Create success response\n * @param message Success message\n * @return Map containing success response\n */\n public Map<String, Object> createSuccessResponse(String message) {\n Map<String, Object> response = new HashMap<>();\n response.put(\"success\", true);\n response.put(\"message\", message);\n response.put(\"timestamp\", System.currentTimeMillis());\n return response;\n }\n \n /**\n * Create success response with data\n * @param message Success message\n * @param data Response data\n * @return Map containing success response with data\n */\n public Map<String, Object> createSuccessResponse(String message, Object data) {\n Map<String, Object> response = createSuccessResponse(message);\n response.put(\"data\", data);\n return response;\n }\n \n /**\n * Create error response\n * @param message Error message\n * @return Map containing error response\n */\n public Map<String, Object> createErrorResponse(String message) {\n Map<String, Object> response = new HashMap<>();\n response.put(\"success\", false);\n response.put(\"message\", message);\n response.put(\"timestamp\", System.currentTimeMillis());\n return response;\n }\n \n /**\n * Create error response with error code\n * @param message Error message\n * @param errorCode Error code\n * @return Map containing error response with error code\n */\n public Map<String, Object> createErrorResponse(String message, String errorCode) {\n Map<String, Object> response = createErrorResponse(message);\n response.put(\"errorCode\", errorCode);\n return response;\n }\n \n /**\n * Create validation error response\n * @param message Validation error message\n * @param errors List of validation errors\n * @return Map containing validation error response\n */\n public Map<String, Object> createValidationErrorResponse(String message, Object errors) {\n Map<String, Object> response = createErrorResponse(message, \"VALIDATION_ERROR\");\n response.put(\"errors\", errors);\n return response;\n }\n \n /**\n * Create unauthorized response\n * @return Map containing unauthorized response\n */\n public Map<String, Object> createUnauthorizedResponse() {\n return createErrorResponse(\"Unauthorized: Admin login required\", \"UNAUTHORIZED\");\n }\n \n /**\n * Create not found response\n * @param resource Resource that was not found\n * @return Map containing not found response\n */\n public Map<String, Object> createNotFoundResponse(String resource) {\n return createErrorResponse(resource + \" not found\", \"NOT_FOUND\");\n }\n \n /**\n * Create response based on operation result\n * @param success Whether operation was successful\n * @param successMessage Message for success case\n * @param errorMessage Message for error case\n * @return Map containing appropriate response\n */\n public Map<String, Object> createResponse(boolean success, String successMessage, String errorMessage) {\n if (success) {\n return createSuccessResponse(successMessage);\n } else {\n return createErrorResponse(errorMessage);\n }\n }\n \n /**\n * Create response with data based on operation result\n * @param success Whether operation was successful\n * @param successMessage Message for success case\n * @param errorMessage Message for error case\n * @param data Data to include in success response\n * @return Map containing appropriate response\n */\n public Map<String, Object> createResponse(boolean success, String successMessage, \n String errorMessage, Object data) {\n if (success) {\n return createSuccessResponse(successMessage, data);\n } else {\n return createErrorResponse(errorMessage);\n }\n }\n \n /**\n * Create paginated response\n * @param data List of data items\n * @param page Current page number\n * @param pageSize Number of items per page\n * @param totalItems Total number of items\n * @return Map containing paginated response\n */\n public Map<String, Object> createPaginatedResponse(Object data, int page, int pageSize, long totalItems) {\n Map<String, Object> response = createSuccessResponse(\"Data retrieved successfully\", data);\n \n Map<String, Object> pagination = new HashMap<>();\n pagination.put(\"page\", page);\n pagination.put(\"pageSize\", pageSize);\n pagination.put(\"totalItems\", totalItems);\n pagination.put(\"totalPages\", (int) Math.ceil((double) totalItems / pageSize));\n \n response.put(\"pagination\", pagination);\n return response;\n }\n \n /**\n * Response types enum for factory method selection\n */\n public enum ResponseType {\n SUCCESS,\n ERROR,\n VALIDATION_ERROR,\n UNAUTHORIZED,\n NOT_FOUND\n }\n \n /**\n * Factory method to create response based on type\n * @param type Response type\n * @param message Response message\n * @param additionalData Additional data (optional)\n * @return Map containing response\n */\n public Map<String, Object> createResponse(ResponseType type, String message, Object... additionalData) {\n switch (type) {\n case SUCCESS:\n if (additionalData.length > 0) {\n return createSuccessResponse(message, additionalData[0]);\n }\n return createSuccessResponse(message);\n \n case ERROR:\n if (additionalData.length > 0 && additionalData[0] instanceof String) {\n return createErrorResponse(message, (String) additionalData[0]);\n }\n return createErrorResponse(message);\n \n case VALIDATION_ERROR:\n if (additionalData.length > 0) {\n return createValidationErrorResponse(message, additionalData[0]);\n }\n return createErrorResponse(message, \"VALIDATION_ERROR\");\n \n case UNAUTHORIZED:\n return createUnauthorizedResponse();\n \n case NOT_FOUND:\n return createNotFoundResponse(message);\n \n default:\n return createErrorResponse(\"Unknown response type\");\n }\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Now let me create a ResponseFactory for standardized API responses:
