","workspace_file_chunks":[]},{"status":"success","request_id":"28f7fa5b-f5ef-40a4-85d0-e0890f2b8fbe","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01Y5Fss9sH47Fan9uNq9t7n9","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "src/main/java/com/example/pahanaedubackend/factory/ValidationFactory.java", "file_content": "package com.example.pahanaedubackend.factory;\n\nimport com.example.pahanaedubackend.util.ValidationUtil;\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.function.Function;\n\n/**\n * Factory Pattern implementation for creating validation functions\n * Provides centralized validation logic creation and management\n */\npublic class ValidationFactory {\n \n // Singleton instance\n private static ValidationFactory instance;\n \n // Map to store validation functions\n private final Map<String, Function<Object[], ValidationUtil.ValidationResult>> validators;\n \n // Private constructor to prevent direct instantiation\n private ValidationFactory() {\n validators = new HashMap<>();\n initializeValidators();\n }\n \n /**\n * Get singleton instance of ValidationFactory\n * @return ValidationFactory instance\n */\n public static synchronized ValidationFactory getInstance() {\n if (instance == null) {\n instance = new ValidationFactory();\n }\n return instance;\n }\n \n /**\n * Initialize built-in validators\n */\n private void initializeValidators() {\n // Customer validation\n validators.put(\"customer\", args -> {\n if (args.length < 5) {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n result.addError(\"Insufficient parameters for customer validation\");\n return result;\n }\n return ValidationUtil.validateCustomer(\n (String) args[0], (String) args[1], (String) args[2], \n (String) args[3], (Integer) args[4]\n );\n });\n \n // Item validation\n validators.put(\"item\", args -> {\n if (args.length < 3) {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n result.addError(\"Insufficient parameters for item validation\");\n return result;\n }\n return ValidationUtil.validateItem(\n (String) args[0], (Double) args[1], (Integer) args[2]\n );\n });\n \n // Login validation\n validators.put(\"login\", args -> {\n if (args.length < 2) {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n result.addError(\"Insufficient parameters for login validation\");\n return result;\n }\n return ValidationUtil.validateLogin((String) args[0], (String) args[1]);\n });\n \n // Required field validation\n validators.put(\"required\", args -> {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n if (args.length < 2) {\n result.addError(\"Insufficient parameters for required field validation\");\n return result;\n }\n \n String fieldName = (String) args[0];\n Object value = args[1];\n \n if (!ValidationUtil.isNotEmpty(value != null ? value.toString() : null)) {\n result.addError(fieldName + \" is required\");\n }\n return result;\n });\n \n // Length validation\n validators.put(\"length\", args -> {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n if (args.length < 4) {\n result.addError(\"Insufficient parameters for length validation\");\n return result;\n }\n \n String fieldName = (String) args[0];\n String value = (String) args[1];\n Integer minLength = (Integer) args[2];\n Integer maxLength = (Integer) args[3];\n \n if (!ValidationUtil.isValidLength(value, minLength, maxLength)) {\n result.addError(fieldName + \" must be between \" + minLength + \" and \" + maxLength + \" characters\");\n }\n return result;\n });\n \n // Phone validation\n validators.put(\"phone\", args -> {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n if (args.length < 2) {\n result.addError(\"Insufficient parameters for phone validation\");\n return result;\n }\n \n String fieldName = (String) args[0];\n String phone = (String) args[1];\n \n if (!ValidationUtil.isValidPhone(phone)) {\n result.addError(fieldName + \" must be a valid 10-digit phone number\");\n }\n return result;\n });\n \n // Account number validation\n validators.put(\"accountNumber\", args -> {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n if (args.length < 2) {\n result.addError(\"Insufficient parameters for account number validation\");\n return result;\n }\n \n String fieldName = (String) args[0];\n String accountNumber = (String) args[1];\n \n if (!ValidationUtil.isValidAccountNumber(accountNumber)) {\n result.addError(fieldName + \" must be 6-12 alphanumeric characters\");\n }\n return result;\n });\n \n // Numeric range validation\n validators.put(\"numericRange\", args -> {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n if (args.length < 4) {\n result.addError(\"Insufficient parameters for numeric range validation\");\n return result;\n }\n \n String fieldName = (String) args[0];\n Double value = (Double) args[1];\n Double min = (Double) args[2];\n Double max = (Double) args[3];\n \n if (!ValidationUtil.isValidNumber(value, min, max)) {\n result.addError(fieldName + \" must be between \" + min + \" and \" + max);\n }\n return result;\n });\n \n // Integer range validation\n validators.put(\"integerRange\", args -> {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n if (args.length < 4) {\n result.addError(\"Insufficient parameters for integer range validation\");\n return result;\n }\n \n String fieldName = (String) args[0];\n Integer value = (Integer) args[1];\n Integer min = (Integer) args[2];\n Integer max = (Integer) args[3];\n \n if (!ValidationUtil.isValidInteger(value, min, max)) {\n result.addError(fieldName + \" must be between \" + min + \" and \" + max);\n }\n return result;\n });\n }\n \n /**\n * Get validator by type\n * @param validatorType Type of validator\n * @return Validation function\n */\n public Function<Object[], ValidationUtil.ValidationResult> getValidator(String validatorType) {\n return validators.get(validatorType.toLowerCase());\n }\n \n /**\n * Create validator by type\n * Factory method to create validation function\n * @param validatorType Type of validator to create\n * @return Validation function or null if type not found\n */\n public Function<Object[], ValidationUtil.ValidationResult> createValidator(String validatorType) {\n return getValidator(validatorType);\n }\n \n /**\n * Validate using specific validator type\n * @param validatorType Type of validator to use\n * @param args Arguments for validation\n * @return ValidationResult\n */\n public ValidationUtil.ValidationResult validate(String validatorType, Object... args) {\n Function<Object[], ValidationUtil.ValidationResult> validator = getValidator(validatorType);\n if (validator == null) {\n ValidationUtil.ValidationResult result = new ValidationUtil.ValidationResult();\n result.addError(\"Unknown validator type: \" + validatorType);\n return result;\n }\n return validator.apply(args);\n }\n \n /**\n * Register custom validator\n * @param validatorType Type name for the validator\n * @param validator Validation function\n */\n public void registerValidator(String validatorType, \n Function<Object[], ValidationUtil.ValidationResult> validator) {\n validators.put(validatorType.toLowerCase(), validator);\n }\n \n /**\n * Check if validator type is supported\n * @param validatorType Type to check\n * @return true if supported, false otherwise\n */\n public boolean isValidatorTypeSupported(String validatorType) {\n return validators.containsKey(validatorType.toLowerCase());\n }\n \n /**\n * Get all supported validator types\n * @return Array of supported validator type names\n */\n public String[] getSupportedValidatorTypes() {\n return validators.keySet().toArray(new String[0]);\n }\n \n /**\n * Remove validator\n * @param validatorType Type of validator to remove\n * @return true if removed, false if not found\n */\n public boolean removeValidator(String validatorType) {\n return validators.remove(validatorType.toLowerCase()) != null;\n }\n \n /**\n * Clear all validators\n */\n public void clearValidators() {\n validators.clear();\n }\n \n /**\n * Reset to default validators\n */\n public void resetToDefaults() {\n validators.clear();\n initializeValidators();\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"Now let me create a ValidationFactory that works with our existing ValidationUtil:
