 1	package com.example.pahanaedubackend.exception;
 2	
 3	/**
 4	 * Custom exception for validation errors
 5	 */
 6	public class ValidationException extends Exception {
 7	 private final String field;
 8	 private final String errorCode;
 9	 
 10	 public ValidationException(String message) {
 11	 super(message);
 12	 this.field = null;
 13	 this.errorCode = "VALIDATION_ERROR";
 14	 }
 15	 
 16	 public ValidationException(String message, String field) {
 17	 super(message);
 18	 this.field = field;
 19	 this.errorCode = "VALIDATION_ERROR";
 20	 }
 21	 
 22	 public ValidationException(String message, String field, String errorCode) {
 23	 super(message);
 24	 this.field = field;
 25	 this.errorCode = errorCode;
 26	 }
 27	 
 28	 public String getField() {
 29	 return field;
 30	 }
 31	 
 32	 public String getErrorCode() {
 33	 return errorCode;
 34	 }
 35	}
