 42	 customer.setFullName((String) data.get("fullName"));
 43	 customer.setTelephone((String) data.get("telephone"));
 44	 customer.setAddress((String) data.get("address"));
 45	
 46	 // Handle unitsConsumed which can be either Integer or String
 47	 Object unitsConsumedObj = data.get("unitsConsumed");
 48	 int unitsConsumed;
 49	 if (unitsConsumedObj instanceof Integer) {
 50	 unitsConsumed = (Integer) unitsConsumedObj;
 51	 } else if (unitsConsumedObj instanceof String) {
 52	 unitsConsumed = Integer.parseInt((String) unitsConsumedObj);
 53	 } else {
 54	 throw new IllegalArgumentException("Invalid unitsConsumed value: " + unitsConsumedObj);
 55	 }
 56	 customer.setUnitsConsumed(unitsConsumed);
 57	
 58	 boolean success = customerService.registerCustomer(customer);
 59	
 60	 Map<String, Object> result = new HashMap<>();
 61	 result.put("success", success);
 62	 result.put("message", success ? "Customer registered successfully" : "Customer registration failed");
 63	
 64	 mapper.writeValue(response.getWriter(), result);
 65	 }
 66	}
