 13	import java.util.ArrayList;
 14	import java.util.Date;
 15	import java.util.List;
 16	import java.util.Map;
 17	
 18	public class BillService {
 19	 private final BillDAO billDAO;
 20	 private final ItemDAO itemDAO;
 21	 private final AuditManager auditManager;
 22	
 23	 public BillService() {
 24	 DAOFactory factory = DAOFactory.getInstance();
 25	 this.billDAO = factory.getBillDAO();
 26	 this.itemDAO = factory.getItemDAO();
 27	 this.auditManager = AuditManager.getInstance();
 28	 }
 29	
 30	 public int createBill(String customerAccountNumber, List<BillItem> billItems) {
 31	 double total = 0.0;
 32	 List<BillItem> validItems = new ArrayList<>();
 33	
 34	 for (BillItem billItem : billItems) {
 35	 Item item = itemDAO.getItemById(billItem.getItemId());
 36	 if (item != null && item.getQuantity() >= billItem.getQuantity()) {
 37	 double itemTotal = item.getPrice() * billItem.getQuantity();
 38	 total += itemTotal;
 39	
 40	 billItem.setPrice(item.getPrice());
 41	 validItems.add(billItem);
 42	
 43	 // update item stock
 44	 itemDAO.updateStock(item.getId(), item.getQuantity() - billItem.getQuantity());
 45	 } else {
 46	 return -1; // insufficient stock or invalid item
 47	 }
 48	 }
 49	
 50	 Bill bill = new Bill();
 51	 bill.setBillDate(new Date());
 52	 bill.setTotal(total);
 53	 bill.setCustomerAccountNumber(customerAccountNumber);
 54	
 55	 return billDAO.createBill(bill, validItems);
 56	 }
 57	
 58	 public Map<String, Object> getBillDetails(int billId) {
 59	 return billDAO.getBillDetails(billId);
 60	 }
 61	}
