 1	package com.example.pahanaedubackend.util;
 2	
 3	import javax.servlet.*;
 4	import javax.servlet.annotation.WebFilter;
 5	import javax.servlet.http.HttpServletRequest;
 6	import javax.servlet.http.HttpServletResponse;
 7	import java.io.IOException;
 8	
 9	@WebFilter("/*")
 10	public class CorsFilter implements Filter {
 11	 @Override
 12	 public void init(FilterConfig filterConfig) throws ServletException {
 13	 // You can leave it empty if no initialization is needed
 14	 }
 15	
 16	 @Override
 17	 public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
 18	 throws IOException, ServletException {
 19	
 20	 HttpServletRequest req = (HttpServletRequest) request;
 21	 HttpServletResponse res = (HttpServletResponse) response;
 22	
 23	 // Set CORS headers
 24	 res.setHeader("Access-Control-Allow-Origin", "*");
 25	 res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
 26	 res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
 27	
 28	 // For preflight requests
 29	 if ("OPTIONS".equalsIgnoreCase(req.getMethod())) {
 30	 res.setStatus(HttpServletResponse.SC_OK);
 31	 return;
 32	 }
 33	
 34	 // Continue to next filter or servlet
 35	 chain.doFilter(request, response);
 36	 }
 37	
 38	 @Override
 39	 public void destroy() {
 40	 // You can leave it empty if no resource cleanup is needed
 41	 }
 42	}
