 15	public class BillService {
 16	 private final BillDAO billDAO;
 17	 private final ItemDAO itemDAO;
 18	
 19	 // Constructor using Factory Pattern
 20	 public BillService() {
 21	 DAOFactory daoFactory = DAOFactory.getInstance();
 22	 this.billDAO = daoFactory.getBillDAO();
 23	 this.itemDAO = daoFactory.getItemDAO();
 24	 }
 25	
 26	 public int createBill(String customerAccountNumber, List<BillItem> billItems) {
 27	 double total = 0.0;
 28	 List<BillItem> validItems = new ArrayList<>();
 29	
 30	 for (BillItem billItem : billItems) {
 31	 Item item = itemDAO.getItemById(billItem.getItemId());
 32	 if (item != null && item.getQuantity() >= billItem.getQuantity()) {
 33	 double itemTotal = item.getPrice() * billItem.getQuantity();
 34	 total += itemTotal;
 35	
 36	 billItem.setPrice(item.getPrice());
 37	 validItems.add(billItem);
 38	
 39	 // update item stock
 40	 itemDAO.updateStock(item.getId(), item.getQuantity() - billItem.getQuantity());
 41	 } else {
 42	 return -1; // insufficient stock or invalid item
 43	 }
 44	 }
