 122	 /**
 123	 * Validates customer data
 124	 * @param accountNumber Customer account number
 125	 * @param fullName Customer full name
 126	 * @param telephone Customer telephone
 127	 * @param address Customer address
 128	 * @param unitsConsumed Units consumed
 129	 * @return ValidationResult with validation status and errors
 130	 */
 131	 public static ValidationResult validateCustomer(String accountNumber, String fullName,
 132	 String telephone, String address, int unitsConsumed) {
 133	 ValidationResult result = new ValidationResult();
 134	
 135	 // Validate account number
 136	 if (!isNotEmpty(accountNumber)) {
 137	 result.addError("Account number is required");
 138	 } else if (!isValidAccountNumber(accountNumber)) {
 139	 result.addError("Account number must be 6-12 alphanumeric characters");
 140	 }
 141	
 142	 // Validate full name
 143	 if (!isNotEmpty(fullName)) {
 144	 result.addError("Full name is required");
 145	 } else if (!isValidLength(fullName, 2, 100)) {
 146	 result.addError("Full name must be between 2 and 100 characters");
 147	 }
 148	
 149	 // Validate telephone
 150	 if (!isNotEmpty(telephone)) {
 151	 result.addError("Telephone number is required");
 152	 } else if (!isValidPhone(telephone)) {
 153	 result.addError("Telephone number must be exactly 10 digits");
 154	 }
 155	
 156	 // Validate address
 157	 if (!isNotEmpty(address)) {
 158	 result.addError("Address is required");
 159	 } else if (!isValidLength(address, 10, 255)) {
 160	 result.addError("Address must be between 10 and 255 characters");
 161	 }
 162	
 163	 // Validate units consumed
 164	 if (!isValidInteger(unitsConsumed, 0, 10000)) {
 165	 result.addError("Units consumed must be between 0 and 10,000");
 166	 }
 167	
 168	 return result;
 169	 }
