 13	public class CustomerDAO {
 14	 public boolean addCustomer(Customer customer) {
 15	 String sql = "INSERT INTO customer (account_number, full_name, telephone, address, units_consumed) VALUES (?, ?, ?, ?, ?)";
 16	
 17	 try (Connection conn = DBUtil.getInstance().getConnection();
 18	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 19	
 20	 stmt.setString(1, customer.getAccountNumber());
 21	 stmt.setString(2, customer.getFullName());
 22	 stmt.setString(3, customer.getTelephone());
 23	 stmt.setString(4, customer.getAddress());
 24	 stmt.setInt(5, customer.getUnitsConsumed());
 25	
 26	 return stmt.executeUpdate() > 0;
 27	 } catch (SQLException e) {
 28	 e.printStackTrace();
 29	 return false;
 30	 }
 31	 }
 32	
 33	 public Customer getCustomerByAccountNumber(String accountNumber) {
 34	 String sql = "SELECT * FROM customer WHERE account_number = ?";
 35	 try (Connection conn = DBUtil.getInstance().getConnection();
 36	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 37	
 38	 stmt.setString(1, accountNumber);
 39	 ResultSet rs = stmt.executeQuery();
 40	
 41	 if (rs.next()) {
 42	 Customer customer = new Customer();
 43	 customer.setAccountNumber(rs.getString("account_number"));
 44	 customer.setFullName(rs.getString("full_name"));
 45	 customer.setAddress(rs.getString("address"));
 46	 customer.setTelephone(rs.getString("telephone"));// hashed password
 47	 return customer;
 48	 }
 49	
 50	 } catch (SQLException e) {
 51	 e.printStackTrace();
 52	 }
 53	 return null;
 54	 }
