 1	package com.example.pahanaedubackend.service;
 2	
 3	import com.example.pahanaedubackend.dao.BillDAO;
 4	import com.example.pahanaedubackend.dao.ItemDAO;
 5	import com.example.pahanaedubackend.model.Bill;
 6	import com.example.pahanaedubackend.model.BillItem;
 7	import com.example.pahanaedubackend.model.Item;
 8	import com.example.pahanaedubackend.util.DBUtil;
 9	
 10	import java.util.ArrayList;
 11	import java.util.Date;
 12	import java.util.List;
 13	import java.util.Map;
 14	
 15	public class BillService {
 16	 private final BillDAO billDAO;
 17	 private final ItemDAO itemDAO;
 18	
 19	 // Constructor using Factory Pattern
 20	 public BillService() {
 21	 DAOFactory daoFactory = DAOFactory.getInstance();
 22	 this.billDAO = daoFactory.getBillDAO();
 23	 this.itemDAO = daoFactory.getItemDAO();
 24	 }
 25	
 26	 public int createBill(String customerAccountNumber, List<BillItem> billItems) {
 27	 double total = 0.0;
 28	 List<BillItem> validItems = new ArrayList<>();
 29	
 30	 for (BillItem billItem : billItems) {
 31	 Item item = itemDAO.getItemById(billItem.getItemId());
 32	 if (item != null && item.getQuantity() >= billItem.getQuantity()) {
 33	 double itemTotal = item.getPrice() * billItem.getQuantity();
 34	 total += itemTotal;
 35	
 36	 billItem.setPrice(item.getPrice());
 37	 validItems.add(billItem);
 38	
 39	 // update item stock
 40	 itemDAO.updateStock(item.getId(), item.getQuantity() - billItem.getQuantity());
 41	 } else {
 42	 return -1; // insufficient stock or invalid item
 43	 }
 44	 }
 45	
 46	 Bill bill = new Bill();
 47	 bill.setBillDate(new Date());
 48	 bill.setTotal(total);
 49	 bill.setCustomerAccountNumber(customerAccountNumber);
 50	
 51	 return billDAO.createBill(bill, validItems);
 52	 }
 53	
 54	 public Map<String, Object> getBillDetails(int billId) {
 55	 return billDAO.getBillDetails(billId);
 56	 }
 57	}
